// HasParishes applies the HasEdge predicate on the "parishes" edge.
func HasParishes() predicate.Diocese {
	return predicate.Diocese(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, ParishesTable, ParishesColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasParishesWith applies the HasEdge predicate on the "parishes" edge with a given conditions (other predicates).
func HasParishesWith(preds ...predicate.Parish) predicate.Diocese {
	return predicate.Diocese(func(s *sql.Selector) {
		step := newParishesStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

